-- G13 (suite20d e02, 2026-09-30): Tool_Catalog registration of check_research_feasibility v3. No table or column
-- changes.
--
-- check_research_feasibility v3: when the question names specific entities (BBCA), a request that reads every entity
-- of its table is refused (SCOPE_WIDER_THAN_QUESTION) unless the angle declares it in the new broad_scope field with
-- a reason. e02 read every stock (2,590,834 rows) for a question about BBCA and its bundle was refused as too large.
-- Generated from the market-ai-orc tool definition (tests/test_multi_angle.py fails when it drifts); inactive like
-- every other market-ai-orc row. The v1 and v2 rows stay as history; v3 copies v2's limits and output schema and adds
-- what changed. The latest version is read with ORDER BY length(version) DESC, version DESC.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '1min';

DO $preflight$
BEGIN
    IF EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'check_research_feasibility' AND version = 'v3') THEN
        RAISE EXCEPTION 'check_research_feasibility v3 is already registered';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'check_research_feasibility' AND version = 'v2') THEN
        RAISE EXCEPTION 'check_research_feasibility v2 (migration 20260930_002) is required';
    END IF;
END;
$preflight$;

INSERT INTO public."Tool_Catalog" (
    tool_name, tool_family, tool_type, purpose, input_schema, output_schema,
    execution_type, handler_name, default_output_rows, max_output_rows,
    max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
    timeout_seconds, max_output_bytes, max_llm_result_rows,
    max_llm_result_bytes, max_llm_result_tokens,
    requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
    tool_specific_limits, version, is_active
)
