       v2.requires_analytics_worker, v2.requires_feature_catalog, v2.requires_data_readiness,
       (v2.tool_specific_limits - 'replaces_version') || '{"broad_scope":"recorded in research_data_plan.broad_scope","replaces_version":"v2","scope_check":"G13 (suite20d e02, 2026-09-30): a request that reads every entity of its table while the question names specific entities is refused (SCOPE_WIDER_THAN_QUESTION) unless the angle declares it in broad_scope with a reason; the entity check reads the Governor''s dimension values"}'::jsonb,
       'v3', false
FROM public."Tool_Catalog" AS v2
WHERE v2.tool_name = 'check_research_feasibility' AND v2.version = 'v2';

DO $verify$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE tool_name = 'check_research_feasibility' AND version = 'v3'
          AND NOT is_active AND tool_specific_limits->>'runtime_service' = 'market-ai-orc'
          AND tool_specific_limits->>'replaces_version' = 'v2') <> 1 THEN
        RAISE EXCEPTION 'Expected one inactive check_research_feasibility v3 row that replaces v2';
    END IF;
    IF (SELECT input_schema->'properties'->'angles'->'items'->'required' ? 'broad_scope' FROM public."Tool_Catalog"
          WHERE tool_name = 'check_research_feasibility' AND version = 'v3') IS NOT TRUE THEN
        RAISE EXCEPTION 'check_research_feasibility v3 does not carry broad_scope';
    END IF;
    IF (SELECT version FROM public."Tool_Catalog" WHERE tool_name = 'check_research_feasibility'
          ORDER BY length(version) DESC, version DESC LIMIT 1) <> 'v3' THEN
        RAISE EXCEPTION 'check_research_feasibility v3 is not the latest version';
    END IF;
END;
$verify$;

COMMIT;
